// Images embedded as base64 data URIs instead of local file requires.
// This is specifically to work around an Expo Snack import bug where
// binary image assets pulled from a GitHub repo fail to upload
// ("Failed to upload file asset" / validation error). Inlining them as
// strings sidesteps Snack's asset pipeline entirely, since they're no
// longer files Snack has to fetch and process separately.
//
// If/when you move off Snack and back to local `expo start` + EAS Build,
// you can switch these back to require('../assets/logo.png') etc. for a
// smaller bundle and normal image caching — that's the better long-term
// approach, this is a Snack-specific workaround.

export const LOGO_DATA_URI = "data:image/png;base64,";

export const BANNER_DATA_URI = "data:image/jpeg;base64,";
